export function infantHTML(course,records,parentOrigin){
 const safe=x=>JSON.stringify(x).replace(/</g,'\\u003c');
 return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aula infantil</title><style>*{box-sizing:border-box}body{margin:0;background:#faf8ef;color:#214d35;font:17px/1.7 system-ui,sans-serif}header{padding:22px 30px;background:#214d35;color:white}h1{font-size:32px;line-height:1.15}h2{font-size:27px;line-height:1.2}h3{font-size:19px}button{font:inherit;cursor:pointer;border:1px solid #a5b38f;border-radius:9px;padding:10px 16px;background:#fff;color:#214d35}button:focus-visible,input:focus-visible{outline:3px solid #a25d28;outline-offset:4px}button[aria-current=true],.primary{background:#214d35;color:white}nav{display:grid;gap:10px;align-content:start}nav button{text-align:left}main{max-width:1180px;margin:auto;padding:30px;display:grid;grid-template-columns:260px 1fr;gap:35px}article{background:white;padding:32px;border-radius:16px;border:1px solid #dde3d1}.box{background:#edf2e1;padding:18px;border-radius:10px}li{padding:6px 0}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}label{display:block;padding:8px}fieldset{border:1px solid #d6dfc7;border-radius:8px}.note{font-size:13px;color:#596b4e}progress{width:100%;accent-color:#678d49}#feedback{font-weight:600}#result{border-top:1px solid #ccd5bc;margin-top:25px}button:disabled{opacity:.5;cursor:default}@media(max-width:700px){main{grid-template-columns:1fr;padding:15px;gap:20px}article{padding:20px}nav{grid-template-columns:1fr 1fr}nav button{font-size:13px}h1{font-size:27px}}@media print{header,nav,.toolbar,fieldset,#feedback{display:none}main{display:block}article{border:0;padding:0}}</style></head><body><header><span>CAMPO EDUCA · PEQUEÑOS EXPLORADORES</span><h1 id="title"></h1><p id="meta"></p></header><main><aside><h2>Mi recorrido</h2><p id="progress-label"></p><progress id="progress" max="4" value="0"></progress><nav aria-label="Lecciones" id="lessons"></nav><p class="note">Trabaja con un adulto. No compartas aquí nombres, direcciones ni fotos de menores.</p></aside><article id="lesson" tabindex="-1"></article></main><script>const course=${safe(course)},initial=${safe(records)},parentOrigin=${safe(parentOrigin)};(${reader.toString()})();<\/script></body></html>`;
}
function reader(){
 const el=id=>document.getElementById(id),node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
 let done=[],current=0;try{const raw=JSON.parse(initial['agro-course-done']||'[]');done=Array.isArray(raw)?[...new Set(raw.filter(n=>Number.isInteger(n)&&n>=0&&n<course.lessons.length))]:[];current=Math.max(0,Math.min(course.lessons.length-1,Number(initial['agro-last-lesson'])||0));}catch{}
 function save(key,value){parent.postMessage({type:'campo-save-learning',courseId:course.id,key,value:String(value)},parentOrigin);}
 el('title').textContent=course.icon+' '+course.title;el('meta').textContent=course.age+' · 4 lecciones · Acompañamiento adulto · Práctica sin calificación oficial';
 function render(focus=false){
  const lesson=course.lessons[current],area=el('lesson');area.replaceChildren();
  el('progress').max=course.lessons.length;el('progress').value=done.length;el('progress-label').textContent=done.length+' de '+course.lessons.length+' lecciones marcadas';el('lessons').replaceChildren();
  course.lessons.forEach((l,i)=>{const b=node('button',(done.includes(i)?'✓ ':'')+(i+1)+'. '+l.title);b.type='button';b.setAttribute('aria-current',String(i===current));b.onclick=()=>{current=i;save('agro-last-lesson',current);render(true);};el('lessons').append(b);});
  area.append(node('p','LECCIÓN '+(current+1)),node('h2',lesson.title),node('p','Tu misión: '+lesson.goal),node('p',lesson.text));
  const materials=node('div');materials.className='box';materials.append(node('h3','Antes de empezar'),node('p',lesson.materials),node('p','Un adulto revisa alergias, materiales y el lugar. No pruebes semillas ni plantas; evita herramientas cortantes, productos químicos y animales desconocidos. Lávate las manos al terminar.'));area.append(materials,node('h3','Manos a la aventura'));
  const steps=node('ol');lesson.steps.forEach(s=>steps.append(node('li',s)));area.append(steps,node('h3','Comprueba lo que descubriste'));
  const form=node('form'),fieldset=node('fieldset'),legend=node('legend',lesson.question);fieldset.append(legend);
  lesson.options.forEach((option,i)=>{const label=node('label'),input=node('input');input.type='radio';input.name='answer';input.value=i;input.required=true;label.append(input,document.createTextNode(' '+option));fieldset.append(label);});
  const check=node('button','Comprobar respuesta');check.type='submit';const feedback=node('p');feedback.id='feedback';feedback.setAttribute('role','status');form.append(fieldset,check,feedback);form.onsubmit=e=>{e.preventDefault();const answer=Number(new FormData(form).get('answer'));feedback.textContent=(answer===lesson.answer?'¡Bien observado! ':'Revisemos juntos. ')+lesson.feedback;};area.append(form,node('h3','Tu cuaderno de exploración'),node('p',lesson.record),node('p','Puedes escribir, dibujar o dictar tu respuesta a un adulto en un cuaderno. No hace falta subir datos personales.'));
  const toolbar=node('div');toolbar.className='toolbar';const mark=node('button',done.includes(current)?'✓ Lección marcada':'Marcar lección realizada');mark.className='primary';mark.onclick=()=>{if(!done.includes(current))done.push(current);save('agro-course-done',JSON.stringify(done));render();};const next=node('button','Siguiente lección →');next.disabled=current===course.lessons.length-1;next.onclick=()=>{current++;save('agro-last-lesson',current);render(true);};const print=node('button','Imprimir esta lección');print.onclick=()=>window.print();toolbar.append(mark,next,print);area.append(toolbar);
  if(done.length===course.lessons.length){const result=node('section');result.id='result';result.append(node('h3','¡Recorrido completado!'),node('p','Revisa tu proyecto final con el adulto que te acompaña. Comparte algo que observaste, algo que aprendiste y una pregunta que quieras seguir explorando.'),node('p','La marca de avance registra tu actividad. No constituye una evaluación oficial ni emite un certificado.'));area.append(result);}
  if(focus)area.focus();
 }
 render();
}
